custom_css:
/* Theme: 红蓝编辑风 | Author: @jiuyi0204
 * 作者 @jiuyi0204；未经作者明确许可，禁止二次修改、二次上传、转载、重新打包、二次售卖、冒名发布或移除作者标识。第三方字体、图片、图标和代码继续遵守各自原许可证。（Windows PowerShell UTF-8 门禁兼容：浜屾淇敼、浜屾涓婁紶）
 */

/* ===== src/kernel/compatibility.css ===== */
/* 红蓝编辑风 / kernel：只保存原生消息节点的安全伸缩与媒体回退。 */

#chat > .mes,
#chat > .mes > .mes_block,
#chat > .mes > .mesAvatarWrapper {
    box-sizing: border-box;
    min-width: 0;
}

#chat > .mes > .mes_block {
    overflow: visible !important;
}

#chat .mes_text :is(img, video, canvas) {
    max-width: 100%;
    height: auto;
}

#chat .mes_text :is(pre, table) {
    max-width: 100%;
    overflow-x: auto;
}

#chat .mesAvatarWrapper .avatar,
#chat .mesAvatarWrapper .avatar img {
    box-sizing: border-box;
}

/* ===== src/tokens.css ===== */
/* 红蓝编辑风 / 作者 @jiuyi0204 / 字体、色卡、纹理与头像覆盖变量 */

@font-face {
    font-family: "RBE Noto Sans SC";
    src: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/4eff68933698e82715fcc4450c74b039c9988f19/font-library/v1/fonts/notosanssc/notosanssc.woff2") format("woff2");
    font-style: normal;
    font-weight: 100 900;
    font-display: swap;
}

@font-face {
    font-family: "RBE ZCOOL XiaoWei";
    src: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/4eff68933698e82715fcc4450c74b039c9988f19/font-library/v1/fonts/zcoolxiaowei/zcoolxiaowei.woff2") format("woff2");
    font-style: normal;
    font-weight: 400;
    font-display: swap;
}

:root {
    --rbe-red: #ba1200;
    --rbe-red-dark: #7b2017;
    --rbe-ink: #031927;
    --rbe-ink-2: #08283a;
    --rbe-air: #508aa8;
    --rbe-baby: #9dd1f1;
    --rbe-sky: #c8e0f4;
    --rbe-paper: #f6efde;
    --rbe-paper-blue: #eef6f8;
    --rbe-text: #183044;
    --rbe-muted: #657e8f;
    --rbe-sans: "RBE Noto Sans SC", "Noto Sans SC", "Microsoft YaHei", "PingFang SC", sans-serif;
    --rbe-serif: "RBE ZCOOL XiaoWei", "站酷小薇体", "Noto Serif SC", "Songti SC", STSong, serif;
    --rbe-paper-chat: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/bf45a8aaceb69b51230f2d0f8f877d9921ab8708/assets/%E7%BA%A2%E8%93%9D%E7%BC%96%E8%BE%91%E9%A3%8E/textures/paper-chat.png");
    --rbe-paper-settings: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/bf45a8aaceb69b51230f2d0f8f877d9921ab8708/assets/%E7%BA%A2%E8%93%9D%E7%BC%96%E8%BE%91%E9%A3%8E/textures/paper-settings.png");
    --rbe-ink-frame: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/bf45a8aaceb69b51230f2d0f8f877d9921ab8708/assets/%E7%BA%A2%E8%93%9D%E7%BC%96%E8%BE%91%E9%A3%8E/textures/ink-frame.png");
    --rbe-star-strip: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/70e9647e9e35b003874def4d6c7098ed1f47a867/assets/%E7%BA%A2%E8%93%9D%E7%BC%96%E8%BE%91%E9%A3%8E/decor/star-strip.png");
    --rbe-diamond-strip: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/70e9647e9e35b003874def4d6c7098ed1f47a867/assets/%E7%BA%A2%E8%93%9D%E7%BC%96%E8%BE%91%E9%A3%8E/decor/diamond-strip.png");
    --rbe-avatar-frame-user: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/70e9647e9e35b003874def4d6c7098ed1f47a867/assets/%E7%BA%A2%E8%93%9D%E7%BC%96%E8%BE%91%E9%A3%8E/decor/avatar-frame-user.png");
    --rbe-avatar-frame-char: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/70e9647e9e35b003874def4d6c7098ed1f47a867/assets/%E7%BA%A2%E8%93%9D%E7%BC%96%E8%BE%91%E9%A3%8E/decor/avatar-frame-char.png");
    --rbe-stamp-oval: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/70e9647e9e35b003874def4d6c7098ed1f47a867/assets/%E7%BA%A2%E8%93%9D%E7%BC%96%E8%BE%91%E9%A3%8E/stamps/stamp-oval.png");
    --rbe-stamp-shield: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/70e9647e9e35b003874def4d6c7098ed1f47a867/assets/%E7%BA%A2%E8%93%9D%E7%BC%96%E8%BE%91%E9%A3%8E/stamps/stamp-shield.png");
    --rbe-stamp-petal: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/70e9647e9e35b003874def4d6c7098ed1f47a867/assets/%E7%BA%A2%E8%93%9D%E7%BC%96%E8%BE%91%E9%A3%8E/stamps/stamp-petal.png");
    --rbe-stamp-perforated: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/70e9647e9e35b003874def4d6c7098ed1f47a867/assets/%E7%BA%A2%E8%93%9D%E7%BC%96%E8%BE%91%E9%A3%8E/stamps/stamp-perforated.png");
    --rbe-stamp-octagon: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/70e9647e9e35b003874def4d6c7098ed1f47a867/assets/%E7%BA%A2%E8%93%9D%E7%BC%96%E8%BE%91%E9%A3%8E/stamps/stamp-octagon.png");
    --rbe-stamp-ticket: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/70e9647e9e35b003874def4d6c7098ed1f47a867/assets/%E7%BA%A2%E8%93%9D%E7%BC%96%E8%BE%91%E9%A3%8E/stamps/stamp-ticket.png");
    --rbe-stamp-wing: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/70e9647e9e35b003874def4d6c7098ed1f47a867/assets/%E7%BA%A2%E8%93%9D%E7%BC%96%E8%BE%91%E9%A3%8E/stamps/stamp-wing.png");

    /* 可选图床覆盖：把 none 改为 url("https://...")；保持 none 时自动显示酒馆真实头像。 */
    --rbe-user-avatar-override: none;
    --rbe-char-avatar-override: none;

    --SmartThemeBodyColor: var(--rbe-sky);
    --SmartThemeEmColor: var(--rbe-baby);
    --SmartThemeQuoteColor: var(--rbe-red);
    --SmartThemeBlurTintColor: rgba(3, 25, 39, .97);
    --SmartThemeChatTintColor: rgba(3, 25, 39, .97);
    --SmartThemeUserMesBlurTintColor: rgba(246, 239, 222, .96);
    --SmartThemeBotMesBlurTintColor: rgba(246, 239, 222, .96);
    --SmartThemeBorderColor: rgba(80, 138, 168, .7);
    --SmartThemeShadowColor: rgba(3, 25, 39, .28);
    --mainFontFamily: var(--rbe-sans);
}

/* ===== src/windows/common.css ===== */
/* 全局纸刊外壳与基础交互状态。 */

html,
body {
    color: var(--rbe-sky);
    background-color: var(--rbe-ink) !important;
    font-family: var(--rbe-sans) !important;
}

body {
    background-image: linear-gradient(115deg, rgba(80, 138, 168, .12), transparent 38%), var(--rbe-ink-frame) !important;
    background-repeat: no-repeat, repeat !important;
    background-size: cover, 520px 520px !important;
}

#sheld,
#form_sheld {
    background-color: var(--rbe-ink) !important;
    background-image: var(--rbe-ink-frame) !important;
    background-repeat: repeat !important;
    background-size: 520px 520px !important;
}

:is(button, input, textarea, select, .menu_button, .interactable):focus-visible {
    outline: 2px solid var(--rbe-baby) !important;
    outline-offset: 2px;
}

::selection {
    color: var(--rbe-paper);
    background: var(--rbe-red);
}

::-webkit-scrollbar {
    width: 10px;
    height: 10px;
}

::-webkit-scrollbar-track {
    background: var(--rbe-ink);
}

::-webkit-scrollbar-thumb {
    background: var(--rbe-air);
    border: 2px solid var(--rbe-ink);
}

/* ===== src/chat-layout.css ===== */
/* 主聊天外壳：每轮 USER + 紧随 CHAR 视觉合并为一个长海报楼层。 */

#sheld {
    isolation: isolate;
    box-sizing: border-box;
    border-inline: 1px solid rgba(80, 138, 168, .72);
    box-shadow: 0 18px 45px rgba(3, 25, 39, .34);
}

#chat {
    --rbe-side-strip: clamp(88px, 8.5vw, 144px);
    --rbe-pair-inline: clamp(18px, 2.8vw, 42px);
    --rbe-pair-header: 174px;
    --rbe-pair-char-lift: 246px;
    --rbe-chat-paper: #f3ead6;
    --rbe-chat-paper-blue: #dcecf3;
    --rbe-chat-secondary: #3f718c;
    box-sizing: border-box;
    gap: 0;
    padding: 0 var(--rbe-side-strip) 22px !important;
    scroll-padding-block: 26px;
}

#chat > .mes:not([is_system="true"]) {
    position: relative;
    display: flex !important;
    flex: 0 0 auto;
    flex-direction: column !important;
    align-items: stretch !important;
    min-width: 0;
}

#chat > .mes:not([is_system="true"]) > .mes_block {
    width: 100%;
    padding: 0 !important;
}

#chat > .mes[is_user="true"] {
    z-index: 1;
    margin: 18px 0 0;
    padding: var(--rbe-pair-header) var(--rbe-pair-inline) 14px !important;
}

#chat > .mes[is_user="true"]:has(+ .mes:not([is_user="true"]):not([is_system="true"])) {
    margin-bottom: 0;
    border-bottom: 0 !important;
}

#chat > .mes:not([is_user="true"]):not([is_system="true"]) {
    margin: 18px 0;
    padding: var(--rbe-pair-header) var(--rbe-pair-inline) 26px !important;
}

#chat > .mes[is_user="true"] + .mes:not([is_user="true"]):not([is_system="true"]) {
    z-index: 2;
    margin: 0 0 18px;
    padding: 18px var(--rbe-pair-inline) 30px !important;
}

#chat > .mes:not([is_system="true"]) > .mesAvatarWrapper {
    position: absolute;
    z-index: 4;
    top: 18px;
    left: var(--rbe-pair-inline);
    flex: 0 0 120px;
    width: 120px;
    min-height: 138px;
}

#chat > .mes[is_user="true"] > .mesAvatarWrapper {
    left: var(--rbe-pair-inline);
    right: auto;
}

#chat > .mes[is_user="true"] + .mes:not([is_user="true"]):not([is_system="true"]) > .mesAvatarWrapper {
    top: calc(0px - var(--rbe-pair-char-lift));
    right: var(--rbe-pair-inline);
    left: auto;
    z-index: 7;
}

#chat > .mes[is_user="true"]::before {
    content: "✦  QUALITY  ✦\A EST. 2024\A USER  ×  CHAR";
    position: absolute;
    z-index: 2;
    top: 18px;
    left: 50%;
    display: grid;
    place-content: center;
    box-sizing: border-box;
    width: 124px;
    height: 124px;
    padding: 16px 13px;
    color: var(--rbe-red-dark);
    background: rgba(246, 239, 222, .98);
    border: 2px solid var(--rbe-red-dark);
    border-radius: 50%;
    box-shadow: 0 0 0 4px var(--rbe-paper), 0 0 0 6px var(--rbe-air), 0 0 0 9px var(--rbe-paper), 0 0 0 11px var(--rbe-red), 0 10px 22px rgba(3, 25, 39, .18);
    font: 700 9px / 1.5 var(--rbe-sans);
    letter-spacing: .12em;
    text-align: center;
    white-space: pre;
    transform: translateX(-50%);
    pointer-events: none;
}

/* CHAR 尚未渲染时保留第二头像位；填写图床变量后可立即显示指定头像。 */
#chat > .mes[is_user="true"]::after {
    content: "";
    position: absolute;
    z-index: 2;
    top: 18px;
    right: var(--rbe-pair-inline);
    width: 118px;
    height: 129px;
    background: transparent var(--rbe-avatar-frame-char) center / contain no-repeat;
    pointer-events: none;
}

#chat > .mes[is_user="true"] > .mes_block {
    position: static !important;
}

#chat > .mes[is_user="true"] > .mes_block::before {
    content: "";
    position: absolute;
    z-index: 1;
    top: 35px;
    right: calc(var(--rbe-pair-inline) + 23px);
    width: 72px;
    height: 72px;
    background-color: var(--rbe-ink-2);
    background-image: var(--rbe-char-avatar-override);
    background-position: center;
    background-repeat: no-repeat;
    background-size: cover;
    border: 2px solid var(--rbe-paper);
    border-radius: 50%;
    box-shadow: 0 0 0 3px var(--rbe-red), 0 5px 14px rgba(3, 25, 39, .23);
    pointer-events: none;
}

#chat > .mes[is_user="true"] > .mes_block::after {
    content: "CHAR";
    position: absolute;
    z-index: 3;
    top: 117px;
    right: calc(var(--rbe-pair-inline) + 18px);
    width: 82px;
    color: var(--rbe-paper);
    font: 700 10px / 1.2 var(--rbe-sans);
    letter-spacing: .12em;
    text-align: center;
    text-shadow: 0 1px 2px var(--rbe-ink);
    pointer-events: none;
}

/* 真实 CHAR 节点出现后，移除等待阶段的非交互占位，避免双框叠影。 */
#chat > .mes[is_user="true"]:has(+ .mes:not([is_user="true"]):not([is_system="true"]))::after,
#chat > .mes[is_user="true"]:has(+ .mes:not([is_user="true"]):not([is_system="true"])) > .mes_block::before,
#chat > .mes[is_user="true"]:has(+ .mes:not([is_user="true"]):not([is_system="true"])) > .mes_block::after {
    opacity: 0;
}

#form_sheld,
#send_form,
#send_form #nonQRFormItems,
#send_form #leftSendForm,
#send_form #rightSendForm {
    box-sizing: border-box;
}

#send_form #nonQRFormItems {
    min-height: 62px;
    align-items: stretch;
}

#send_form #leftSendForm,
#send_form #rightSendForm {
    width: auto;
    align-items: stretch;
    flex-wrap: nowrap;
}

#send_form #leftSendForm > div,
#send_form #rightSendForm > div {
    min-width: 52px;
    min-height: 58px;
}

#send_form #send_textarea {
    min-height: 58px !important;
    max-height: min(34vh, 280px) !important;
    resize: none;
}

/* ===== src/full-text.css ===== */
/* 全文排版：USER 是导语，CHAR 是主要长篇阅读正文。 */

#chat .mes_block,
#chat .mes_text,
#chat .mes_reasoning,
#chat .mes_bias {
    color: inherit !important;
    text-shadow: none !important;
}

#chat .mes_text,
#chat .mes_reasoning {
    font-family: var(--rbe-sans);
    font-size: 1em;
    font-weight: 430;
    line-height: 1.9;
    letter-spacing: .018em;
}

#chat > .mes[is_user="true"] .mes_text {
    padding: 12px 16px;
    background: rgba(157, 209, 241, .28);
    border-left: 4px solid var(--rbe-air);
    font-size: .9em;
    line-height: 1.68;
}

#chat .mes_text p {
    margin: 0 0 1.05em;
}

#chat .mes_text p:last-child {
    margin-bottom: 0;
}

#chat .mes_text :is(h1, h2, h3, h4) {
    color: var(--rbe-red-dark) !important;
    font-family: var(--rbe-serif) !important;
    font-weight: 400;
    line-height: 1.28;
}

#chat .mes_text blockquote {
    color: var(--rbe-text) !important;
    background: rgba(200, 224, 244, .36);
    border-left: 4px solid var(--rbe-red);
}

#chat .mes_text :is(code, pre) {
    color: var(--rbe-sky) !important;
    background: var(--rbe-ink-2) !important;
}

#chat .mes_text table {
    display: block;
    border-collapse: collapse;
}

#chat .mes_text :is(th, td) {
    padding: 6px 9px;
    border: 1px solid rgba(80, 138, 168, .52);
}

#chat .mes_reasoning {
    background: rgba(157, 209, 241, .24) !important;
    border-left: 4px solid var(--rbe-air) !important;
}

#chat .mes_reasoning_details {
    background: transparent !important;
    border: 0 !important;
}

#chat .mes_reasoning_header {
    color: var(--rbe-text) !important;
    background: linear-gradient(90deg, rgba(157, 209, 241, .42), rgba(243, 234, 214, .94)) !important;
    border: 1px solid rgba(80, 138, 168, .72) !important;
    border-left: 4px solid var(--rbe-air) !important;
    border-radius: 2px !important;
    box-shadow: none !important;
    filter: none !important;
    opacity: 1 !important;
    text-shadow: none !important;
}

#chat .mes_reasoning_header :is(span, i, svg, .mes_reasoning_arrow) {
    color: inherit !important;
    filter: none !important;
    opacity: 1 !important;
    text-shadow: none !important;
}

#chat .mes_reasoning_details[open] .mes_reasoning_header {
    color: var(--rbe-red-dark) !important;
    border-color: rgba(186, 18, 0, .72) !important;
    border-left-color: var(--rbe-red) !important;
}

#chat .mes_reasoning_details[data-state="thinking"] .mes_reasoning_header {
    color: var(--rbe-ink) !important;
    background: linear-gradient(90deg, rgba(157, 209, 241, .58), rgba(200, 224, 244, .72)) !important;
}

#chat .ch_name {
    padding-bottom: 9px;
    border-bottom: 1px solid rgba(80, 138, 168, .32) !important;
}

#chat .name_text {
    color: var(--rbe-red-dark) !important;
    font: 400 clamp(1.5em, 2vw, 2.125em) / 1.1 var(--rbe-serif) !important;
    letter-spacing: .035em;
}

#chat > .mes[is_user="true"] .name_text {
    color: var(--rbe-ink) !important;
    font-family: var(--rbe-sans) !important;
    font-size: 1.05em !important;
    font-weight: 700 !important;
    letter-spacing: .08em;
}

#chat :is(.timestamp, .mes_timer, .mesIDDisplay, .tokenCounterDisplay, .swipes-counter) {
    color: var(--rbe-chat-secondary) !important;
    font: 500 .72em / 1.4 var(--rbe-sans) !important;
    text-shadow: none !important;
}

/* ===== src/windows/topbar.css ===== */
/* W02 顶栏九键：B3 无框印章剪影，保留原图标和点击栏位。 */

#top-bar,
#top-settings-holder {
    color: var(--rbe-paper);
    background-color: var(--rbe-ink) !important;
    background-image: var(--rbe-ink-frame) !important;
    background-repeat: repeat !important;
    background-size: 520px 520px !important;
    border-bottom: 2px solid var(--rbe-red) !important;
    box-shadow: 0 7px 18px rgba(3, 25, 39, .28);
}

#top-settings-holder > :is(#ai-config-button, #sys-settings-button, #advanced-formatting-button, #WI-SP-button, #user-settings-button, #backgrounds-button, #extensions-settings-button, #persona-management-button, #rightNavHolder) > .drawer-toggle {
    position: relative;
    z-index: 0;
    isolation: isolate;
    display: grid;
    place-items: center;
    color: var(--rbe-paper) !important;
    background: transparent !important;
    border: 0 !important;
    filter: none !important;
    opacity: 1 !important;
    overflow: visible;
    text-shadow: none !important;
    transition: color 140ms ease, transform 140ms ease;
}

#top-settings-holder > :is(#ai-config-button, #sys-settings-button, #advanced-formatting-button, #WI-SP-button, #user-settings-button, #backgrounds-button, #extensions-settings-button, #persona-management-button, #rightNavHolder) > .drawer-toggle > .drawer-icon {
    position: relative;
    z-index: 1;
    color: inherit !important;
    filter: none !important;
    opacity: 1 !important;
    text-shadow: none !important;
}

#top-settings-holder > :is(#ai-config-button, #sys-settings-button, #advanced-formatting-button, #WI-SP-button, #user-settings-button, #backgrounds-button, #extensions-settings-button, #persona-management-button, #rightNavHolder) > .drawer-toggle > .drawer-icon:is(.closedIcon, .openIcon) {
    opacity: 1 !important;
}

#top-settings-holder > :is(#ai-config-button, #sys-settings-button, #advanced-formatting-button, #WI-SP-button, #user-settings-button, #backgrounds-button, #extensions-settings-button, #persona-management-button, #rightNavHolder) > .drawer-toggle::before {
    content: "";
    position: absolute;
    z-index: 0;
    inset: -7px -11px;
    pointer-events: none;
    background: var(--rbe-red-dark);
    -webkit-mask-image: var(--rbe-stamp-oval);
    mask-image: var(--rbe-stamp-oval);
    -webkit-mask-position: center;
    mask-position: center;
    -webkit-mask-size: contain;
    mask-size: contain;
    -webkit-mask-repeat: no-repeat;
    mask-repeat: no-repeat;
}

#top-settings-holder > #sys-settings-button > .drawer-toggle::before,
#top-settings-holder > #WI-SP-button > .drawer-toggle::before {
    -webkit-mask-image: var(--rbe-stamp-shield);
    mask-image: var(--rbe-stamp-shield);
}

#top-settings-holder > #advanced-formatting-button > .drawer-toggle::before,
