/* ===== src/windows/chat.css ===== */
/* W01 主聊天：成对楼层、真实双头像与 B3 消息操作。 */

#chat {
    color: var(--rbe-text);
    background-color: var(--rbe-chat-paper) !important;
    background-image: var(--rbe-star-strip), var(--rbe-diamond-strip), var(--rbe-paper-chat) !important;
    background-position: left top, right top, center top !important;
    background-repeat: repeat-y, repeat-y, repeat !important;
    background-size: var(--rbe-side-strip) auto, var(--rbe-side-strip) auto, 460px 460px !important;
    background-blend-mode: normal, normal, multiply !important;
    text-shadow: none !important;
}

#chat > .mes:not([is_system="true"]) {
    color: var(--rbe-text) !important;
    background-color: rgba(243, 234, 214, .96) !important;
    background-image: var(--rbe-paper-chat) !important;
    background-position: center top !important;
    background-repeat: repeat !important;
    background-size: 460px 460px !important;
    background-blend-mode: multiply !important;
    border: 0 !important;
    border-inline: 1px solid rgba(80, 138, 168, .38) !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    text-shadow: none !important;
}

#chat > .mes[is_user="true"] {
    border-top: 5px solid var(--rbe-air) !important;
}

#chat > .mes[is_user="true"]:not(:has(+ .mes:not([is_user="true"]):not([is_system="true"]))) {
    border-bottom: 5px solid var(--rbe-red) !important;
}

#chat > .mes:not([is_user="true"]):not([is_system="true"]) {
    border-block: 5px solid var(--rbe-red) !important;
}

#chat > .mes[is_user="true"] + .mes:not([is_user="true"]):not([is_system="true"]) {
    border-top: 1px solid rgba(186, 18, 0, .24) !important;
    border-bottom: 5px solid var(--rbe-red) !important;
}

#chat > .mes[is_system="true"] {
    color: var(--rbe-sky) !important;
    background: rgba(3, 25, 39, .94) !important;
    border-bottom: 1px solid var(--rbe-air) !important;
}

#chat > .mes:not([is_system="true"]) > .mesAvatarWrapper::before {
    content: "";
    position: absolute;
    z-index: 2;
    pointer-events: none;
    top: 0;
    left: 50%;
    width: 118px;
    height: 129px;
    background: transparent var(--rbe-avatar-frame-char) center / contain no-repeat;
    transform: translateX(-50%);
}

#chat > .mes[is_user="true"] > .mesAvatarWrapper::before {
    background-image: var(--rbe-avatar-frame-user);
}

#chat .avatar {
    position: relative;
    z-index: 1;
    width: 72px !important;
    height: 72px !important;
    margin: 17px auto 41px !important;
    overflow: hidden !important;
    background: var(--rbe-ink-2);
    border: 0 !important;
    border-radius: 50% !important;
}

#chat .avatar img {
    position: relative;
    z-index: 1;
    width: 100% !important;
    height: 100% !important;
    object-fit: cover;
    object-position: center;
    border: 2px solid var(--rbe-paper) !important;
    border-radius: 50% !important;
    box-shadow: 0 0 0 3px var(--rbe-red), 0 5px 14px rgba(3, 25, 39, .23) !important;
}

#chat > .mes[is_user="true"] .avatar img {
    box-shadow: 0 0 0 3px var(--rbe-air), 0 5px 14px rgba(3, 25, 39, .23) !important;
}

/* 图床覆盖层为空时透明，原生头像继续自动跟随 Persona/角色。 */
#chat .avatar::after {
    content: "";
    position: absolute;
    z-index: 2;
    inset: 0;
    background-image: var(--rbe-char-avatar-override);
    background-position: center;
    background-repeat: no-repeat;
    background-size: cover;
    border-radius: 50%;
    pointer-events: none;
}

#chat > .mes[is_user="true"] .avatar::after {
    background-image: var(--rbe-user-avatar-override);
}

#chat .mesAvatarWrapper::after {
    content: "CHAR";
    position: absolute;
    z-index: 3;
    pointer-events: none;
    top: 99px;
    left: 18px;
    right: 18px;
    display: grid;
    place-items: center;
    box-sizing: border-box;
    min-height: 20px;
    padding: 1px 5px;
    color: var(--rbe-paper);
    background: rgba(123, 32, 23, .42);
    font: 700 10px / 1.2 var(--rbe-sans);
    letter-spacing: .12em;
    text-align: center;
    text-shadow: 0 1px 2px var(--rbe-ink);
}

#chat > .mes[is_user="true"] .mesAvatarWrapper::after {
    content: "USER";
    background: rgba(80, 138, 168, .42);
}

#chat .mes_buttons {
    color: var(--rbe-red-dark);
}

#chat :is(.mes_buttons, .mes_edit_buttons) {
    filter: none !important;
}

#chat :is(.mes_button, .mes_edit_buttons .menu_button) {
    position: relative;
    z-index: 0;
    isolation: isolate;
    min-width: 32px;
    min-height: 32px;
    color: var(--rbe-paper) !important;
    background: transparent !important;
    border: 0 !important;
    border-radius: 0 !important;
    filter: none !important;
    opacity: 1 !important;
    text-shadow: none !important;
}

#chat :is(.mes_button, .mes_edit_buttons .menu_button)::before,
#chat :is(.mes_button, .mes_edit_buttons .menu_button) > :is(i, span, svg) {
    position: relative;
    z-index: 1;
    color: inherit !important;
    filter: none !important;
    opacity: 1 !important;
    text-shadow: none !important;
}

#chat :is(.mes_button, .mes_edit_buttons .menu_button)::after {
    content: "";
    position: absolute;
    z-index: 0;
    inset: 1px;
    pointer-events: none;
    background: var(--rbe-red-dark);
    -webkit-mask-image: var(--rbe-stamp-oval);
    mask-image: var(--rbe-stamp-oval);
    -webkit-mask-position: center;
    mask-position: center;
    -webkit-mask-size: contain;
    mask-size: contain;
    -webkit-mask-repeat: no-repeat;
    mask-repeat: no-repeat;
}

#chat .mes_buttons > :nth-child(2)::after { -webkit-mask-image: var(--rbe-stamp-ticket); mask-image: var(--rbe-stamp-ticket); }
#chat .mes_buttons > :nth-child(3)::after { -webkit-mask-image: var(--rbe-stamp-shield); mask-image: var(--rbe-stamp-shield); }
#chat .mes_buttons > :nth-child(4)::after { -webkit-mask-image: var(--rbe-stamp-petal); mask-image: var(--rbe-stamp-petal); }
#chat .mes_buttons > :nth-child(5)::after { -webkit-mask-image: var(--rbe-stamp-octagon); mask-image: var(--rbe-stamp-octagon); }
#chat .mes_buttons > :nth-child(6)::after { -webkit-mask-image: var(--rbe-stamp-perforated); mask-image: var(--rbe-stamp-perforated); }

#chat :is(.mes_button, .mes_edit_buttons .menu_button):is(:hover, :focus-visible)::after {
    background: var(--rbe-air);
}

#chat :is(.mes_button, .mes_edit_buttons .menu_button):active {
    transform: scale(.96);
}

#chat :is(.mes_button, .mes_edit_buttons .menu_button):is(.disabled, [aria-disabled="true"], :disabled) {
    color: var(--rbe-baby) !important;
    opacity: .72 !important;
}

