/* ===== src/windows/mobile.css ===== */
/* W14 手机端：保留成对楼层与功能入口，只收紧尺寸。 */

@media (max-width: 800px) {
    #form_sheld {
        padding-bottom: env(safe-area-inset-bottom, 0);
    }

    #sheld {
        border-inline: 0;
        box-shadow: none;
    }

    #chat {
        --rbe-side-strip: 32px;
        --rbe-pair-inline: 12px;
        --rbe-pair-header: 132px;
        --rbe-pair-char-lift: 194px;
        padding: 0 var(--rbe-side-strip) 14px !important;
        background-size: var(--rbe-side-strip) auto, var(--rbe-side-strip) auto, 360px 360px !important;
    }

    #chat > .mes[is_user="true"] {
        margin-top: 12px;
        padding: var(--rbe-pair-header) var(--rbe-pair-inline) 10px !important;
    }

    #chat > .mes:not([is_user="true"]):not([is_system="true"]) {
        margin-block: 12px;
        padding: var(--rbe-pair-header) var(--rbe-pair-inline) 20px !important;
    }

    #chat > .mes[is_user="true"] + .mes:not([is_user="true"]):not([is_system="true"]) {
        margin: 0 0 12px;
        padding: 14px var(--rbe-pair-inline) 22px !important;
    }

    #chat > .mes:not([is_system="true"]) > .mesAvatarWrapper {
        top: 12px;
        flex-basis: 88px;
        width: 88px;
        min-height: 102px;
    }

    #chat > .mes[is_user="true"] + .mes:not([is_user="true"]):not([is_system="true"]) > .mesAvatarWrapper {
        top: calc(0px - var(--rbe-pair-char-lift));
    }

    #chat > .mes[is_user="true"]::before {
        top: 17px;
        width: 88px;
        height: 88px;
        padding: 10px 7px;
        box-shadow: 0 0 0 3px var(--rbe-paper), 0 0 0 4px var(--rbe-air), 0 0 0 6px var(--rbe-paper), 0 0 0 7px var(--rbe-red), 0 6px 14px rgba(3, 25, 39, .16);
        font-size: 6.5px;
        letter-spacing: .07em;
    }

    #chat > .mes[is_user="true"]::after,
    #chat > .mes:not([is_system="true"]) > .mesAvatarWrapper::before {
        top: 0;
        width: 86px;
        height: 94px;
    }

    #chat > .mes[is_user="true"]::after {
        top: 12px;
    }

    #chat .avatar {
        width: 52px !important;
        height: 52px !important;
        margin: 13px auto 31px !important;
    }

    #chat .mesAvatarWrapper::after {
        top: 72px;
        left: 12px;
        right: 12px;
        min-height: 15px;
        padding-inline: 2px;
        font-size: 8px;
    }

    #chat > .mes[is_user="true"] > .mes_block::before {
        top: 25px;
        right: calc(var(--rbe-pair-inline) + 17px);
        width: 52px;
        height: 52px;
    }

    #chat > .mes[is_user="true"] > .mes_block::after {
        top: 84px;
        right: calc(var(--rbe-pair-inline) + 11px);
        width: 64px;
        font-size: 8px;
    }

    #chat .name_text {
        font-size: clamp(20px, 6vw, 28px) !important;
    }

    #chat > .mes[is_user="true"] .name_text {
        font-size: 15px !important;
    }

    #chat .mes_text,
    #chat .mes_reasoning {
        font-size: .92em;
        line-height: 1.78 !important;
    }

    #chat > .mes[is_user="true"] .mes_text {
        padding: 10px 11px;
        font-size: .88em;
        line-height: 1.62 !important;
    }

    #send_form #leftSendForm > div,
    #send_form #rightSendForm > div {
        min-width: 42px;
    }

    #send_form #send_textarea {
        padding: 10px !important;
        font-size: .92em !important;
    }

    #top-settings-holder > :is(#ai-config-button, #sys-settings-button, #advanced-formatting-button, #WI-SP-button, #user-settings-button, #backgrounds-button, #extensions-settings-button, #persona-management-button, #rightNavHolder) > .drawer-content,
    #left-nav-panel,
    #AdvancedFormatting,
    #completion_prompt_manager_popup,
    #WorldInfo,
    #world_popup,
    #PersonaManagement,
    #Backgrounds,
    #right-nav-panel {
        width: 100% !important;
        max-width: 100% !important;
        border-inline: 0 !important;
        border-radius: 0 !important;
    }

    .popup,
    .popup-content,
    .modal-content,
    .dialogue_popup {
        max-width: calc(100% - 16px) !important;
        border-radius: 2px !important;
    }
}

/* ===== src/fallback.css ===== */
/* 红蓝编辑风 / 可用性回退。远程图片失败时仍保留纯色、原图标和原头像。 */

#chat .avatar img {
    visibility: visible !important;
}

#top-settings-holder > :is(#ai-config-button, #sys-settings-button, #advanced-formatting-button, #WI-SP-button, #user-settings-button, #backgrounds-button, #extensions-settings-button, #persona-management-button, #rightNavHolder) > .drawer-toggle > .drawer-icon {
    filter: none !important;
    opacity: 1 !important;
}

@supports not ((mask-image: url("x")) or (-webkit-mask-image: url("x"))) {
    #chat :is(.mes_button, .mes_edit_buttons .menu_button)::after,
    #send_form :is(#options_button, #extensionsMenuButton, #send_but, #mes_stop, #mes_continue, #mes_impersonate)::after,
    #top-settings-holder > :is(#ai-config-button, #sys-settings-button, #advanced-formatting-button, #WI-SP-button, #user-settings-button, #backgrounds-button, #extensions-settings-button, #persona-management-button, #rightNavHolder) > .drawer-toggle::before {
        inset: 4px;
        border-radius: 50%;
    }
}

@media (prefers-reduced-motion: reduce) {
    #send_form :is(#options_button, #extensionsMenuButton, #send_but, #mes_stop, #mes_continue, #mes_impersonate),
    #chat :is(.mes_button, .mes_edit_buttons .menu_button),
    #top-settings-holder > :is(#ai-config-button, #sys-settings-button, #advanced-formatting-button, #WI-SP-button, #user-settings-button, #backgrounds-button, #extensions-settings-button, #persona-management-button, #rightNavHolder) > .drawer-toggle {
        transition: none !important;
    }
}
